package com.justenoughmods.achievementguide.mixin;
import com.justenoughmods.achievementguide.integration.spawncare.*;import org.spongepowered.asm.mixin.*;import org.spongepowered.asm.mixin.injection.*;import org.spongepowered.asm.mixin.injection.callback.*;
import net.minecraft.world.level.LevelAccessor;import net.minecraft.world.entity.Entity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.item.Items;import net.mcreator.barnyardbuddies.entity.JacobsSheepEntity;import com.justenoughmods.achievementguide.integration.food.FoodDroppedProof;
@Pseudo @Mixin(targets="net.mcreator.barnyardbuddies.procedures.JacobsSheepRightClickedOnEntityProcedure",remap=false) public abstract class SpawnCareQuestJacobShearMixin { 
 @Unique private static final ThreadLocal<SpawnCareQuestRun> JEM_RUN=new ThreadLocal<>();@Unique private static final ThreadLocal<Boolean> JEM_WOOL=new ThreadLocal<>();
 @Inject(method="execute",at=@At("HEAD"),remap=false) private static void jem$before(LevelAccessor world,Entity entity,Entity source,CallbackInfo ci){var actor=source instanceof Player p?SpawnCareQuestProof.real(p):null;boolean wool=entity instanceof JacobsSheepEntity sheep&&sheep.getEntityData().get(JacobsSheepEntity.DATA_GrowWool);JEM_WOOL.set(wool);JEM_RUN.set(actor!=null&&wool&&actor.getMainHandItem().is(Items.SHEARS)?SpawnCareQuestRun.begin(entity,actor,actor.getMainHandItem()):null);}
 @Inject(method="execute",at=@At("RETURN"),remap=false) private static void jem$after(LevelAccessor world,Entity entity,Entity source,CallbackInfo ci){var run=JEM_RUN.get();JEM_RUN.remove();boolean before=Boolean.TRUE.equals(JEM_WOOL.get());JEM_WOOL.remove();SpawnCareQuestRun.end(run);if(run!=null&&before&&entity instanceof JacobsSheepEntity sheep&&!sheep.getEntityData().get(JacobsSheepEntity.DATA_GrowWool))for(var made:run.created)if(made instanceof ItemEntity drop&&SpawnCareQuestProof.item(drop.getItem()).equals("barnyardbuddies:spotted_wool"))FoodDroppedProof.update(drop,"v3_pet_farm_signatures",drop.getItem().getCount(),run.actor.getUUID());}
 }
